import { Router } from "express";
import { overlaps } from "../lib/overlap.js";
import { rooms, findRoom, bookingsForRoom } from "../store.js";

export const roomsRouter = Router();

interface Slot {
  startsAt: string;
  endsAt: string;
}

const isoDay = /^\d{4}-\d{2}-\d{2}$/;

function dayBounds(date: unknown): Slot | undefined {
  if (typeof date !== "string" || !isoDay.test(date)) return undefined;
  const startsAt = `${date}T00:00:00.000Z`;
  const start = Date.parse(startsAt);
  if (Number.isNaN(start) || new Date(start).toISOString() !== startsAt) return undefined;
  const end = new Date(start + 24 * 60 * 60 * 1000).toISOString();
  return { startsAt, endsAt: end };
}

function freeSlotsForDay(roomId: string, day: Slot): Slot[] {
  const dayStart = Date.parse(day.startsAt);
  const dayEnd = Date.parse(day.endsAt);
  const busy = bookingsForRoom(roomId)
    .filter((booking) => overlaps(day.startsAt, day.endsAt, booking.startsAt, booking.endsAt))
    .map((booking) => ({
      start: Math.max(Date.parse(booking.startsAt), dayStart),
      end: Math.min(Date.parse(booking.endsAt), dayEnd)
    }))
    .sort((a, b) => a.start - b.start);

  const merged = busy.reduce<{ start: number; end: number }[]>((slots, slot) => {
    const previous = slots.at(-1);
    if (!previous || slot.start > previous.end) {
      slots.push(slot);
    } else {
      previous.end = Math.max(previous.end, slot.end);
    }
    return slots;
  }, []);

  const free: Slot[] = [];
  let cursor = dayStart;
  for (const slot of merged) {
    if (cursor < slot.start) {
      free.push({ startsAt: new Date(cursor).toISOString(), endsAt: new Date(slot.start).toISOString() });
    }
    cursor = Math.max(cursor, slot.end);
  }
  if (cursor < dayEnd) {
    free.push({ startsAt: new Date(cursor).toISOString(), endsAt: new Date(dayEnd).toISOString() });
  }
  return free;
}

roomsRouter.get("/", (_req, res) => {
  res.json({ rooms });
});

roomsRouter.get("/:id", (req, res) => {
  const room = findRoom(req.params.id);
  if (!room) {
    res.status(404).json({ error: "salle inconnue" });
    return;
  }
  res.json({ room, bookings: bookingsForRoom(room.id) });
});

roomsRouter.get("/:id/availability", (req, res) => {
  const room = findRoom(req.params.id);
  if (!room) {
    res.status(404).json({ error: "salle inconnue" });
    return;
  }

  const day = dayBounds(req.query.date);
  if (!day) {
    res.status(400).json({ error: "date invalide : date" });
    return;
  }

  res.json({ roomId: room.id, date: req.query.date, slots: freeSlotsForDay(room.id, day) });
});

import { beforeEach, describe, expect, it } from "vitest";
import { bookings } from "../src/store.js";
import { call } from "./http.js";

const initial = bookings.map((booking) => ({ ...booking }));
beforeEach(() => bookings.splice(0, bookings.length, ...initial.map((booking) => ({ ...booking }))));

describe("GET /rooms/:id/availability", () => {
  it("renvoie toute la journee quand la salle est libre", async () => {
    const result = await call("/rooms/labo/availability?date=2026-11-03");

    expect(result).toEqual({
      status: 200,
      body: {
        roomId: "labo",
        date: "2026-11-03",
        slots: [
          { startsAt: "2026-11-03T00:00:00.000Z", endsAt: "2026-11-04T00:00:00.000Z" }
        ]
      }
    });
  });

  it("retire les reservations de la journee demandee", async () => {
    const result = await call("/rooms/salle-a/availability?date=2026-10-05");

    expect(result).toEqual({
      status: 200,
      body: {
        roomId: "salle-a",
        date: "2026-10-05",
        slots: [
          { startsAt: "2026-10-05T00:00:00.000Z", endsAt: "2026-10-05T09:00:00.000Z" },
          { startsAt: "2026-10-05T11:00:00.000Z", endsAt: "2026-10-06T00:00:00.000Z" }
        ]
      }
    });
  });

  it("borne au jour UTC et fusionne les reservations contigues ou chevauchantes", async () => {
    bookings.push(
      {
        id: "bk-midnight",
        roomId: "labo",
        who: "nuit",
        people: 2,
        startsAt: "2026-11-02T22:00:00Z",
        endsAt: "2026-11-03T02:00:00Z",
        price: 160
      },
      {
        id: "bk-early",
        roomId: "labo",
        who: "matin",
        people: 2,
        startsAt: "2026-11-03T02:00:00Z",
        endsAt: "2026-11-03T04:00:00Z",
        price: 80
      },
      {
        id: "bk-overlap",
        roomId: "labo",
        who: "support",
        people: 2,
        startsAt: "2026-11-03T03:30:00Z",
        endsAt: "2026-11-03T05:00:00Z",
        price: 60
      }
    );

    const result = await call("/rooms/labo/availability?date=2026-11-03");

    expect(result.body.slots).toEqual([
      { startsAt: "2026-11-03T05:00:00.000Z", endsAt: "2026-11-04T00:00:00.000Z" }
    ]);
  });

  it("renvoie 404 pour une salle inconnue", async () => {
    expect(await call("/rooms/cave/availability?date=2026-11-03")).toEqual({
      status: 404,
      body: { error: "salle inconnue" }
    });
  });

  it.each([
    "/rooms/labo/availability",
    "/rooms/labo/availability?date=2026-02-30",
    "/rooms/labo/availability?date=2026-11-03T00:00:00Z",
    "/rooms/labo/availability?date=demain",
    "/rooms/labo/availability?date=2026-11-03&date=2026-11-04"
  ])("refuse une date absente, impossible, repetee ou mal formee : %s", async (path) => {
    expect(await call(path)).toEqual({
      status: 400,
      body: { error: "date invalide : date" }
    });
  });
});

