 4	export interface ApiResponse {
 5	  status: number;
 6	  body: Record<string, unknown>;
 7	}
 8	
 9	/** Exerce l'application via une vraie requête HTTP locale et ferme le serveur. */
10	export async function call(path: string, init?: RequestInit): Promise<ApiResponse> {
11	  const server = createApp().listen(0, "127.0.0.1");
12	  try {
13	    await once(server, "listening");
14	    const address = server.address();
15	    if (!address || typeof address === "string") throw new Error("port HTTP absent");
16	    const res = await fetch(`http://127.0.0.1:${address.port}${path}`, init);
17	    return { status: res.status, body: await res.json() as Record<string, unknown> };
18	  } finally {
19	    server.closeAllConnections();
20	    await new Promise<void>((resolve, reject) => server.close((error) => error ? reject(error) : resolve()));
21	  }
22	}

